import {expect} from '@playwright/test';
import {invertCube} from './lut-ui.mjs';
export async function exerciseLutBandWorker(page,module){
 await page.context().route('**/__lut-band-probe.js*',async route=>{
  const url=new URL(route.request().url()),mode=url.searchParams.get('mode'),moduleUrl=new URL(module,url).href;
  await route.fulfill({contentType:'text/javascript',headers:{'Cross-Origin-Embedder-Policy':'require-corp','Cross-Origin-Resource-Policy':'same-origin'},body:`Object.defineProperty(navigator,'hardwareConcurrency',{value:${mode==='serial'?2:8}});Object.defineProperty(navigator,'deviceMemory',{value:8});const Original=Worker;let number=0;globalThis.Worker=class extends Original{constructor(url,options){if(${JSON.stringify(mode)}==='unsupported')throw new Error('Nested workers unsupported');super(url,options);this.number=++number;postMessage({probe:'start'});}postMessage(data,...rest){if(data.buffer){postMessage({probe:'band',bytes:data.buffer.byteLength});if(${JSON.stringify(mode)}==='failure'&&this.number===2){queueMicrotask(()=>this.onerror?.({preventDefault(){}}));return;}}return super.postMessage(data,...rest);}terminate(){postMessage({probe:'stop'});super.terminate();}};await import(${JSON.stringify(moduleUrl)});postMessage({probe:'ready'});`});
 });
 const result=await page.evaluate(async({module,cube})=>{
  const hash=async bytes=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].join(','),lutFile=new File([cube],'bands.cube'),id=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await lutFile.arrayBuffer())),n=>n.toString(16).padStart(2,'0')).join('');
  const w=3200,h=2600,canvas=new OffscreenCanvas(w,h),ctx=canvas.getContext('2d'),data=ctx.createImageData(w,h);for(let i=0;i<data.data.length;i++)data.data[i]=i%4===3?255:(i*157+(i>>13))%256;ctx.putImageData(data,0,0);const file=new File([await canvas.convertToBlob({type:'image/png'})],'bands.png'),before=await hash(await file.arrayBuffer());
  const recipe={version:5,exposure:.2,contrast:0,highlights:0,shadows:0,temperature:0,tint:0,saturation:0,hue:0,hslSaturation:0,lightness:0,curve:[0,.25,.5,.75,1],rotation:0,flipX:false,flipY:false,crop:{x:0,y:0,width:1,height:1},sharpen:0,denoise:0,match:0,preserveLuminance:true,composition:{source_width:w,source_height:h,angle:0},layer_stack:{version:1,layers:[]},lut:{version:1,asset_hash:id,strength:.73,input:'srgb'}};
  const digest=async blob=>{const image=await createImageBitmap(blob),c=new OffscreenCanvas(image.width,image.height),x=c.getContext('2d');x.drawImage(image,0,0);image.close();return hash(x.getImageData(0,0,c.width,c.height).data);},results=[];
  for(const mode of ['serial','parallel','failure','unsupported']){
   const url=new URL('/__lut-band-probe.js',location.href);url.searchParams.set('mode',mode);const worker=new Worker(url,{type:'module'});let token=0,starts=0,stops=0,maxBytes=0;const pending=new Map();let markReady,rejectReady;const ready=new Promise((resolve,reject)=>{markReady=resolve;rejectReady=reject;});worker.onerror=e=>{rejectReady(new Error(e.message));for(const item of pending.values()){clearTimeout(item.timer);item.reject(new Error(e.message));}};
   worker.onmessage=e=>{const m=e.data;if(m.probe){if(m.probe==='ready')markReady();if(m.probe==='start')starts++;if(m.probe==='stop')stops++;maxBytes=Math.max(maxBytes,m.bytes||0);return;}if(m.progress)return;const item=pending.get(m.id);if(!item)return;pending.delete(m.id);clearTimeout(item.timer);m.error?item.reject(new Error(m.error)):m.result&&item.resolve(m.result);};
   const send=data=>new Promise((resolve,reject)=>{const n=++token,timer=setTimeout(()=>reject(new Error('Band export timed out')),45000);pending.set(n,{resolve,reject,timer});worker.postMessage({id:n,...data});});
   try{await ready;await send({action:'open',file});const preview=await send({action:'render',recipe,lut:{id,file:lutFile}}),previewWorkers=starts;const output=await send({action:'export',recipe,lut:{id,file:lutFile},edge:0,format:'png'}),record={mode,hash:await digest(output.blob),width:output.width,height:output.height,previewWorkers,starts,stops,maxBytes};
    if(mode==='parallel'){const spec={version:1,aspect:{width:w/(2*h)*10,height:10},count:2,region:{x:0,y:0,width:1,height:1},basis:{width:w,height:h},angle:0},split=await send({action:'split',recipe,lut:{id,file:lutFile},spec,format:'png',quality:95});record.splitHash=await digest(split.master.blob);record.splitPanels=split.panels.length;record.starts=starts;record.stops=stops;}
    results.push(record);
   }finally{worker.terminate();for(const item of pending.values())clearTimeout(item.timer);}
  }
  return {results,original:before===await hash(await file.arrayBuffer())};
 },{module,cube:invertCube('Bands')});
 expect(result.original).toBe(true);expect(new Set(result.results.map(r=>r.hash)).size).toBe(1);for(const r of result.results){expect(r).toMatchObject({width:3200,height:2600,previewWorkers:0});expect(r.starts).toBe(r.stops);expect(r.maxBytes).toBeLessThanOrEqual(4*1024*1024);}expect(result.results[1].starts).toBe(8);expect(result.results[1].splitHash).toBe(result.results[0].hash);expect(result.results[1].splitPanels).toBe(2);expect(result.results[2].starts).toBe(4);expect(result.results[3].starts).toBe(0);
}
